function norm(arr){ var s=0; for(var i=0;i<arr.length;i++) s+=arr[i]; if(s<=0) return arr.slice();
  var o=[]; for(var i=0;i<arr.length;i++) o.push(arr[i]/s); return o; }
function log2(x){ return Math.log(x)/Math.log(2); }
function kl(p,q){ p=norm(p); q=norm(q); if(p.length!==q.length) return NaN;
  var s=0; for(var i=0;i<p.length;i++){ if(p[i]>0) s+=p[i]*log2(p[i]/(q[i]||1e-12)); } return Math.max(0,s); }
function crossEntropy(p,q){ p=norm(p); q=norm(q); var s=0; for(var i=0;i<p.length;i++){ if(p[i]>0) s+=-p[i]*log2(q[i]||1e-12); } return s; }
function entropy(p){ p=norm(p); var s=0; for(var i=0;i<p.length;i++){ if(p[i]>0) s+=-p[i]*log2(p[i]); } return s; }
var EXPORTS={norm:norm,kl:kl,crossEntropy:crossEntropy,entropy:entropy};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KLForgePure = EXPORTS; }
